/**
 * TEST-UR-11 — txrresults dev-gallery fixture pins (INV-5; ITEM-11).
 *
 * The gallery stories (PROV-UR-8) are driven entirely by the synthetic
 * `fixtures.ts`; these pins keep the "fixture" honest and the board's
 * design-example facts out of the module (FLOW.md: facts shown in the
 * boards are design examples, never data):
 *
 * - every fixture patient id is `S\d{4,}`-shaped (never a board patient id);
 * - the fixture sources carry no decimal literal — every probability is
 *   generated by the spread formula (`fxChance`/`fxHChance`), so none of the
 *   boards' example percentages can be a literal;
 * - no fixture file reads or names the trees the app must not touch
 *   (`restricted/`, `datasets/`, `results/` — nothing is read from outside
 *   this file; the sources are static imports of this module + the generated
 *   client types only);
 * - the gallery mock answers EXACTLY the five Txr operations this node
 *   consumes (getRun, streamRun, getPredictions, listRunLogs,
 *   downloadPredictions) across the JSON cassette and the byte/error mock
 *   routes, and nothing else;
 * - the fixture material through the REAL view model: the H run's compare
 *   report names the three-of-five shared patients and the three biggest
 *   divergences (the card's material), 6 patients differ by ≥ 10 pp, the
 *   running story starts with 11 columns and grows to 12, and the empty run
 *   serves no predictions response (its 409 is a mock route).
 */
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import {
  TXR_ABSTAIN_NOTE,
  TXR_CSV,
  TXR_G_METHODS,
  TXR_RUN_CANNOT,
  TXR_RUN_EMPTY,
  TXR_RUN_G,
  TXR_RUN_H,
  TXR_RUN_RUNNING,
  TXR_PREDICTIONS,
  TXR_PREDICTIONS_GROWN,
  TXR_RUN_HFEW,
  TXR_CANNOT_REASON,
  fxPatientId,
  txrStreamFrames,
} from './fixtures'
import { gallery, txrMockRoutes } from './gallery'
import { buildColumns, compareReport, viewOf } from './lib/heatmap'

const FIXTURE_DIR = fileURLToPath(new URL('.', import.meta.url))

/** The two fixture source files (the pins scan the DATA, never this test). */
function fixtureSourceText(): string {
  return ['fixtures.ts', 'gallery.tsx']
    .map(f => readFileSync(path.join(FIXTURE_DIR, f), 'utf8'))
    .join('\n')
}

/** Every patient id of the fixture predictions, in response order. */
function allPatientIds(): string[] {
  return Object.values(TXR_PREDICTIONS).flatMap(p => p.patients)
}

describe('txrresults fixtures (TEST-UR-11)', () => {
  it('generates only S-prefixed patient ids (the fixture name space, never a board id)', () => {
    const ids = allPatientIds()
    expect(ids.length).toBeGreaterThan(0)
    for (const id of ids) expect(id).toMatch(/^S\d{4,}$/)
    expect(fxPatientId(1)).toBe('S0001')
    expect(ids).toContain('S0001')
  })

  it('carries no board example patient id and no decimal probability literal (INV-5)', () => {
    const source = fixtureSourceText()
    // The boards' patient ids are `P0###`-shaped; every fixture id is an
    // S-number, so a P-prefixed id in the fixture data is a board fact.
    expect(source.match(/P0\d{3}/g)).toBeNull()
    // The spread formula produces the probabilities: no decimal literal may
    // exist in the fixture sources. A dotted pair that is ADJACENT to another
    // digit/dot (a version string's `0.1.0`) is not a number at all — the
    // lookbehind/lookahead pair excludes those spellings together.
    expect(source.match(/(?<![\d.])\d+\.\d+(?![\d.])/g)).toBeNull()
  })

  it('never reads or spells the trees the app must not touch', () => {
    // The module's OWN route strings (`/analysis/:runId/results/…`, the
    // app's URL space) are stripped before the scan: they contain `results/`
    // as a URL segment but name no data tree — the pin is about trees.
    const source = fixtureSourceText()
      .toLowerCase()
      .replace(/\/analysis\/[^'"`]+/g, '')
    for (const forbidden of ['restricted/', 'datasets/', 'results/']) {
      expect(source).not.toContain(forbidden)
    }
    // The imports are static + local-only (plus the generated client types).
    const fixtureSource = readFileSync(path.join(FIXTURE_DIR, 'fixtures.ts'), 'utf8')
    expect(fixtureSource).not.toContain('import(')
    expect(fixtureSource).not.toContain('fetch(')
    expect(fixtureSource).not.toContain('from \'@/modules/')
  })

  it('mocks exactly the five Txr operations this node consumes and nothing else', () => {
    const FIVE = ['getRun', 'streamRun', 'getPredictions', 'listRunLogs', 'downloadPredictions']
    // The cassette keys are the generated `ApiEndpoints` ids (`Txr.getRun`);
    // the mock-route ops are declared unprefixed — both spell the same five.
    const cassetteKeys = Object.keys(gallery.cassette ?? {}).map(k => k.replace(/^Txr\./, ''))
    const routeOps = txrMockRoutes.map(e => e.op)
    // Every cassette key and every mock route is one of the five, and the
    // union covers all five — a new op (or a route for a 6th) fails here.
    for (const key of cassetteKeys) expect(FIVE).toContain(key)
    for (const op of routeOps) expect(FIVE).toContain(op)
    expect([...new Set([...cassetteKeys, ...routeOps])].sort()).toEqual([...FIVE].sort())
  })

  it('builds the G run as the board layout: all methods finished, counts consistent', () => {
    expect(TXR_RUN_G.methods.length).toBe(TXR_G_METHODS)
    expect(TXR_RUN_G.methods.every(m => m.state === 'finished')).toBe(true)
    expect(TXR_RUN_G.counts.finished).toBe(TXR_G_METHODS)
    expect(TXR_RUN_G.predictions_ready).toBe(true)
    const predictions = TXR_PREDICTIONS[TXR_RUN_G.id]
    expect(predictions.patients.length).toBe(38)
    expect(predictions.methods.length).toBe(TXR_G_METHODS)
    // The provider average is the per-patient mean of the generated columns.
    const averages = predictions.average as Array<number | null>
    for (const value of averages) expect(value).not.toBeNull()
    // The abstain note travels with its null probability (the tooltip material).
    const withNote = predictions.methods.flatMap(m => {
      const probabilities = m.probabilities as Array<number | null>
      const notes = m.notes as Array<string | null>
      return notes.map((note, p) => ({ note, prob: probabilities[p] }))
    })
    const abstains = withNote.filter(x => x.note === TXR_ABSTAIN_NOTE)
    expect(abstains.length).toBeGreaterThan(0)
    for (const a of abstains) expect(a.prob).toBeNull()
  })

  it('keeps the running story at 11 columns until the frame, 12 after (INV-1)', () => {
    const predictions = TXR_PREDICTIONS[TXR_RUN_RUNNING.id]
    expect(predictions.methods.length).toBe(TXR_G_METHODS - 1)
    expect(TXR_PREDICTIONS_GROWN.methods.length).toBe(TXR_G_METHODS)
    expect(TXR_RUN_RUNNING.counts.finished).toBe(TXR_G_METHODS - 1)
    expect(TXR_RUN_RUNNING.counts.running).toBe(1)
    // The frame script announces exactly that method's column (its id is on
    // the last spec row) and ends terminal.
    const script = txrStreamFrames(TXR_RUN_RUNNING.id)
    const predictionFrames = script.filter(f => f.event === 'prediction')
    expect(predictionFrames).toHaveLength(1)
    expect((predictionFrames[0].data as { method_id: string }).method_id).toBe(
      TXR_RUN_RUNNING.methods[TXR_RUN_RUNNING.methods.length - 1].method_id,
    )
    expect(script.at(-1)).toEqual({ event: 'status', data: { status: 'finished' } })
  })

  it('carries the cannot-run row with its reason and the mixed-task facts', () => {
    const cannot = TXR_RUN_CANNOT.methods.find(m => m.state === 'cannot_run')
    expect(cannot).toBeDefined()
    expect(cannot!.reason?.code).toBe(TXR_CANNOT_REASON.code)
    expect(cannot!.reason?.detail).toBe(TXR_CANNOT_REASON.detail)
    // Two finished methods on two different tasks — two outcome tabs render.
    const tasks = TXR_RUN_CANNOT.methods.filter(m => m.state === 'finished').map(m => m.task)
    expect(new Set(tasks).size).toBe(2)
    // The cannot-run method is not a predictions column.
    expect(TXR_PREDICTIONS[TXR_RUN_CANNOT.id].methods.map(m => m.method_id)).not.toContain(
      cannot!.method_id,
    )
  })

  it('serves no predictions response for the empty run (its 409 is a mock route)', () => {
    expect(TXR_PREDICTIONS[TXR_RUN_EMPTY.id]).toBeUndefined()
    expect(TXR_RUN_EMPTY.methods.every(m => m.state !== 'finished')).toBe(true)
    expect(TXR_RUN_EMPTY.predictions_ready).toBe(false)
  })

  it('feeds the real compare model the board-shaped report: 3 shared, 3 differ, 6 divergent', () => {
    const predictions = TXR_PREDICTIONS[TXR_RUN_H.id]
    const columns = buildColumns(predictions, 'pfs')
    const view = viewOf(columns, predictions, {
      outcome: 'pfs',
      groups: null,
      methodIds: null,
      search: '',
      sort: 'patient',
      limit: 0,
    })
    expect(view.columns).toHaveLength(2)
    const report = compareReport(view.columns, view.rows)
    expect(report.sharedTop.map(x => x.patientId)).toEqual(['S0028', 'S0025', 'S0022'])
    expect(report.mostDiffering.map(x => x.patientId)).toEqual(['S0014', 'S0017', 'S0011'])
    expect(report.mostDiffering.map(x => x.diffPercent)).toEqual([15, 14, 13])
    expect(report.divergentCount).toBe(6)
    // The H run's board facts: two finished methods, both produced models.
    expect(TXR_RUN_H.methods.filter(m => m.state === 'finished')).toHaveLength(2)
    expect(TXR_RUN_H.models.map(m => m.method_id)).toEqual(
      TXR_RUN_H.methods.map(m => m.method_id),
    )
  })

  it('gives the one-method runs a single column and a produced model', () => {
    expect(TXR_RUN_HFEW.methods.filter(m => m.state === 'finished')).toHaveLength(1)
    const predictions = TXR_PREDICTIONS[TXR_RUN_HFEW.id]
    expect(predictions.methods).toHaveLength(1)
    expect(TXR_RUN_HFEW.models).toHaveLength(1)
  })

  it('builds the CSV from the fixture method columns (the byte passthrough material)', () => {
    const header = TXR_CSV.split('\n')[0]
    expect(header).toBe('patient_id,landmark-cox-current,cox-cutpoint-risk,notes')
    expect(TXR_CSV).toContain('S0009,')
  })

  it('replays only the provider event vocabulary in every frame script', () => {
    const events = new Set(['status', 'method', 'log', 'progress', 'prediction'])
    for (const runId of Object.keys(TXR_PREDICTIONS)) {
      for (const frame of txrStreamFrames(runId)) {
        expect(events.has(frame.event)).toBe(true)
      }
    }
  })
})
